var SIMON_COLORS=['red','green','blue','yellow'];
function simonNext(){ return SIMON_COLORS[Math.floor(Math.random()*4)]; }
function simonVerify(seq, inputs){
  if(inputs.length>seq.length) return false;
  for(var i=0;i<inputs.length;i++){ if(inputs[i]!==seq[i]) return false; }
  return true;
}
function simonWrong(seq, inputs){
  for(var i=0;i<inputs.length;i++){ if(inputs[i]!==seq[i]) return i; }
  return -1;
}
var EXPORTS={simonNext:simonNext,simonVerify:simonVerify,simonWrong:simonWrong,SIMON_COLORS:SIMON_COLORS};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SimonForgePure = EXPORTS; }
